local config = {
  ui_story_30890101_1_dialog_content = "Chief Judge... Sungguh sosok yang mengagumkan...",
  ui_story_30890101_2_dialog_content = "Dia datang ke Colossus untuk urusan publik.",
  ui_story_30890101_3_dialog_content = "Namun, dia tidak banyak bicara. Bahkan ketika semua orang mengobrol dan bersosialisasi, dia diam saja...",
  ui_story_30890101_4_dialog_content = "Sungguh wanita yang cantik... Aku yakin senyumnya bahkan lebih cantik.",
  ui_story_30890101_5_dialog_content = "Navigator?",
  ui_story_30890101_6_dialog_content = "Tidak, tidak, tidak...",
  ui_story_30890101_7_dialog_content = "Bagaimanapun kamu melihatnya, Chief Judge adalah orang yang terlalu serius dan formal untuk dipikirkan seperti itu!",
  ui_story_30890101_8_dialog_content = "PlayerName?",
  ui_story_30890101_9_dialog_content = "Wah!!",
  ui_story_30890101_10_dialog_content = "Chief Judge! A-apa kabar?",
  ui_story_30890101_11_dialog_content = "Panggil saja aku Irridon. Kita bekerja bersama sekarang, tidak perlu terlalu formal begitu.",
  ui_story_30890101_12_dialog_content = "Kudengar kamu mengomentari penampilanku, dan aku sudah berdiri di sini sejak tadi.",
  ui_story_30890101_13_dialog_content = "(Astaga, hukum saja aku daripada dipermalukan di depan umum...!)",
  ui_story_30890101_14_dialog_content = "Ma-maafkan aku!",
  ui_story_30890101_15_dialog_content = "Tidak perlu meminta maaf untuk hal seperti ini.",
  ui_story_30890101_16_dialog_content = "Dilihat dari sudut pandang mana pun, itu adalah pujian. Seharusnya aku tersanjung.",
  ui_story_30890101_17_dialog_content = "Irridon... Kamu tidak seperti yang kukira.",
  ui_story_30890101_18_dialog_content = "Oh? Aku tertarik... Seharusnya aku itu seperti apa bagimu?",
  ui_story_30890101_19_dialog_content = "Anu... Yah, itu hanya... Eh...",
  ui_story_30890101_20_dialog_content = "B-bukan masalah! Selain itu, aku hampir lupa ada suatu hal yang penting untuk didiskusikan denganmu!",
  ui_story_30890101_21_dialog_content = "Ya, aku baru mendengarnya dari Carleen... Kejadian-kejadian aneh terjadi di Colossus, benar?",
  ui_story_30890101_22_dialog_content = "Ya...",
  ui_story_30890101_23_dialog_content = "Makanan kami lenyap dari dapur, meninggalkan jejak yang aneh...",
  ui_story_30890101_24_dialog_content = "Meski hanya beberapa hidangan mengerikan buatan Vice yang tidak akan dilewatkan oleh siapa pun...",
  ui_story_30890101_25_dialog_content = "Namun, kemudian... Kami mulai mendengar suara langkah kaki aneh di luar kamar saat malam...",
  ui_story_30890101_26_dialog_content = "Namun, ketika kuperiksa jejak kaki itu saat pagi, jejaknya sama sekali tidak mirip jejak kaki Aurorian.",
  ui_story_30890101_27_dialog_content = "Jadi, kurasa itu adalah musuh yang belum diketahui...",
  ui_story_30890101_28_dialog_content = "Hmm... Benar-benar aneh.",
  ui_story_30890101_29_dialog_content = "Apakah Colossus pernah ke tempat aneh belakangan ini? Atau apakah kamu pernah melihat orang yang mencurigakan?",
  ui_story_30890101_30_dialog_content = "Sepertinya tidak ada yang mencurigakan.",
  ui_story_30890101_31_dialog_content = "Sementara untuk tempat aneh...",
  ui_story_30890101_32_dialog_content = "Entah apakah ini masuk hitungan, tetapi ketika Colossus harus melakukan pendaratan darurat waktu itu, kami berhenti di suatu reruntuhan.",
  ui_story_30890101_33_dialog_content = "Namun, hanya untuk beberapa menit.",
  ui_story_30890101_34_dialog_content = "Hmm... Begitu, ya. Apakah kamu sudah memulai investigasi formal?",
  ui_story_30890101_35_option_content = "Aku... Tidak bisa...",
  ui_story_30890101_36_dialog_content = "Baiklah... Sebenarnya aku tidak bisa menggunakan Lumina, jadi...",
  ui_story_30890101_37_option_content = "Aku... Aku rasa aku memilikinya?",
  ui_story_30890101_38_dialog_content = "Sepertinya tidak.",
  ui_story_30890101_39_dialog_content = "Sepertinya kamu bicara tanpa tedeng aling-aling...",
  ui_story_30890101_40_dialog_content = "...",
  ui_story_30890101_41_dialog_content = "Aku paham. Aku bisa mengurusnya dari sini.",
  ui_story_30890101_42_dialog_content = "(Tunggu, dia benar-benar menangani kasus ini?!)",
  ui_story_30890101_43_dialog_content = "(Mungkinkah apa pun yang terjadi pada Colossus... adalah rahasia besar Lumopolis?!)",
  ui_story_30890101_44_dialog_content = "Keesokan Harinya",
  ui_story_30890101_45_dialog_content = "Maksudmu, ini semua sudah diurus?",
  ui_story_30890101_46_dialog_content = "Luar biasa, Irridon... Jadi, apa yang ada di balik <color=#FFB400>jejak</color> dan <color=#FFB400>makanan yang hilang</color> itu?",
  ui_story_30890101_47_dialog_content = "Seperti dugaanmu, High-level Eclipsite menyelinap masuk ke kapal saat kamu berhenti di reruntuhan itu.",
  ui_story_30890101_48_option_content = "Kamu menghadapinya sendirian?! Kamu baik-baik saja?!",
  ui_story_30890101_49_dialog_content = "Aku... tidak yakin ini seperti yang kamu harapkan.",
  ui_story_30890101_50_dialog_content = "Aku tidak harus bertarung dengannya, aku hanya <color=#FFB400>menginterogasinya</color>.",
  ui_story_30890101_51_option_content = "High-level Eclipsite! Apakah ia kabur?!",
  ui_story_30890101_52_dialog_content = "Ia tidak kabur.",
  ui_story_30890101_53_dialog_content = "Namun, yakinlah, ia tidak lagi ada di Colossus.",
  ui_story_30890101_54_dialog_content = "Jadi... Apa yang terjadi?",
  ui_story_30890101_55_dialog_content = "Kamu tidak ingat? Kamu bilang sendiri, Colossus berhenti di suatu reruntuhan sebelumnya.",
  ui_story_30890101_56_dialog_content = "Ya, aku ingat dengan jelas... saat itulah...",
  ui_story_30890101_57_dialog_content = "Ia menyelinap ke atas kapal, ya.",
  ui_story_30890101_58_dialog_content = "Namun, ia tidak menyerang Aurorian, juga tidak mencuri informasi rahasia apa pun dari Colossus.",
  ui_story_30890101_59_dialog_content = "Sekarang, katakan apa yang kamu lakukan di sini atau rasakan pedangku.",
  ui_story_30890101_60_dialog_content = "<anim type=Shake><size=35>Hik...</size></anim>",
  ui_story_30890101_61_dialog_content = "Bicaralah!",
  ui_story_30890101_62_dialog_content = "Tidak, kumohon... Eh...",
  ui_story_30890101_63_dialog_content = "Tidak ada darah atau tanda-tanda pertarungan... Kamu tidak berniat untuk menyergap kru?",
  ui_story_30890101_64_dialog_content = "Kuperhatikan salah satu pantri telah dihancurkan...",
  ui_story_30890101_65_dialog_content = "*Mengaum*",
  ui_story_30890101_66_dialog_content = "A-aku... Lapar... Cari... Makanan... Lapar!",
  ui_story_30890101_67_dialog_content = "Jadi... Bisa... Makan lagi...?",
  ui_story_30890101_68_dialog_content = "Makanan Aurorian... Mmm... Enak...",
  ui_story_30890101_69_dialog_content = "Aku... Tidak sakiti... Tidak sakiti Aurorian!",
  ui_story_30890101_70_dialog_content = "(High-level Eclipsite... yang tidak menyakiti siapa pun?)",
  ui_story_30890101_71_dialog_content = "Kamu... Makan? Di sini... Bagus...",
  ui_story_30890101_72_dialog_content = "(Ia... berbagi makanan? Ini bukan perilaku Eclipsite biasa...)",
  ui_story_30890101_73_dialog_content = "(Aku pernah melihat jenis Eclipsites khusus ini sebelumnya—makhluk baik dan damai yang bisa memahami manusia, dan bahkan Aurorian.)",
  ui_story_30890101_74_dialog_content = "(Jika ia adalah salah satunya... mungkin lebih baik kutinggalkan di sini untuk observasi.)",
  ui_story_30890101_75_dialog_content = "Itu pemahamanku...",
  ui_story_30890101_76_dialog_content = "Bahkan seorang Eclipsite berhak mendapatkan <color=#FFB400>pengadilan yang adil</color>. Kamu tidak menyakiti siapa pun, jadi tidak ada alasan bagiku untuk membasmimu.",
  ui_story_30890101_77_dialog_content = "Eh?! Buu-huu...",
  ui_story_30890101_78_dialog_content = "Namun, pencurian makanan adalah tindakan pelanggaran... Dan Colossus butuh lebih banyak staf kebersihan.",
  ui_story_30890101_79_dialog_content = "Jika kamu bersikeras untuk memakan makanan mereka, bersihkan tempat ini!",
  ui_story_30890101_80_dialog_content = "H-hah?!",
  ui_story_30890101_81_dialog_content = "Selama interogasiku, aku juga mengetahui—",
  ui_story_30890101_82_dialog_content = "Bahwa ia menyelinap ke atas Colossus dan mempertaruhkan nyawanya hanya demi memenuhi kebutuhan makanannya.",
  ui_story_30890101_83_dialog_content = "Perilakunya tidak seperti Eclipsite biasa, jadi aku memberinya tes sederhana, untuk membersihkan Colossus.",
  ui_story_30890101_84_dialog_content = "Ia melakukannya tanpa ragu.",
  ui_story_30890101_85_dialog_content = "Seorang Eclipsite yang menyukai makanan Aurorian... Itu luar biasa.",
  ui_story_30890101_86_option_content = "Jadi... Kamu tidak membunuhnya?",
  ui_story_30890101_87_dialog_content = "Aku memberinya makanan, dan mengantar kepergiannya.",
  ui_story_30890101_88_dialog_content = "Sword of Borrowing tidak akan membunuh orang yang tidak bersalah... Jadi, aku menunjukkan belas kasihan kepadanya.",
  ui_story_30890101_89_option_content = "Namun, ia tetaplah Eclipsite!",
  ui_story_30890101_90_dialog_content = "Mungkin Aurorian yang jahat jauh lebih mengerikan ketimbang Eclipsite yang tidak berbahaya...",
  ui_story_30890101_91_dialog_content = "Takkan pernah kubiarkan seorang Aurorian pergi dengan bebas jika tangan mereka berlumuran darah... Aku juga takkan pernah membunuh Eclipsite yang tidak melakukan kesalahan apa pun.",
  ui_story_30890101_92_dialog_content = "Ia... benar-benar menyukai makanan aneh Vice?",
  ui_story_30890101_93_dialog_content = "Semur Octopus kuah susu... Bisakah kamu menyebut itu makanan? Sungguh preferensi yang mengganggu...",
  ui_story_30890101_94_dialog_content = "Lupakan, aku hanya senang tidak ada yang terluka.",
  ui_story_30890101_95_dialog_content = "Jadi, semuanya kini baik-baik saja?",
  ui_story_30890101_96_dialog_content = "Seperti yang kamu bilang, tidak ada yang terluka dan tidak ada yang rusak.",
  ui_story_30890101_97_dialog_content = "Kalau begitu, semua kejadian yang aneh ini... karena Eclipsite itu?",
  ui_story_30890101_98_dialog_content = "Sepertinya begitu.",
  ui_story_30890101_99_dialog_content = "T-tidak ada hal lain yang terjadi?",
  ui_story_30890101_100_dialog_content = "Aku melakukan pencarian penuh di Colossus juga dan tidak menemukan sesuatu yang aneh.",
  ui_story_30890101_101_dialog_content = "B-begitukah... Bagus.",
  ui_story_30890101_102_dialog_content = "Selama ini, kupikir kejadian tersebut mungkin ada hubungannya dengan rahasia Lumopolis yang kelam dan tersembunyi... Aku sampai tidak tidur berhari-hari.",
  ui_story_30890101_103_dialog_content = "Kenapa kamu berpikir begitu?",
  ui_story_30890101_104_dialog_content = "Ketika aku bilang pada Carleen soal ini, dia duduk dan berpikir lama sebelum mengatakan akan mencari orang untuk menanganinya.",
  ui_story_30890101_105_dialog_content = "Tampang Carleen... sangat serius.",
  ui_story_30890101_106_dialog_content = "Hmm...",
  ui_story_30890101_107_dialog_content = "Kurasa dia tahu sesuatu, dan tidak bisa mengurusnya sendiri... Jadi, dia meminta seseorang sepandai kamu!",
  ui_story_30890101_108_dialog_content = "Apa pun kebenarannya... Aku sangat yakin entah bagaimana ini berhubungan dengan Lumopolis!",
  ui_story_30890101_109_dialog_content = "Imajinasimu lumayan juga.",
  ui_story_30890101_110_dialog_content = "Tidak ada salahnya berhati-hati, tetapi masalah ini sudah beres. Kamu bisa beristirahat dengan tenang sekarang.",
  ui_story_30890101_111_dialog_content = "Oh... Aku ingin tahu kenapa ekspresi Carleen begitu muram...",
  ui_story_30890101_112_dialog_content = "Mungkin kamu terlalu memikirkan banyak hal.",
  ui_story_30890101_113_dialog_content = "Aku hampir yakin dia bertanya-tanya siapa yang harus dihubungi untuk masalah ini.",
  ui_story_30890101_114_dialog_content = "Belakangan ini Hall of Justice sedang sibuk, dan sudah lama aku ingin berlibur.",
  ui_story_30890101_X114_dialog_content = "Aku jarang meluangkan waktu untuk diri sendiri, jadi kurasa dia tidak ingin menggangguku.",
  ui_story_30890101_115_dialog_content = "Juga sudah sifatku untuk tidak menolak orang yang membutuhkan atau masalah yang perlu dipecahkan.",
  ui_story_30890101_119_dialog_content = "Hall of Justice... juga tidak seperti yang kuduga.",
  ui_story_30890101_120_dialog_content = "Kurasa semua orang di sana menghabiskan hari-hari mereka dengan membaca dokumen, mengerjakan masalah mereka dengan tampang serius...",
  ui_story_30890101_121_dialog_content = "Namun, ketika melihatmu dan yang lainnya dari Hall of Justice, aku sadar bukan itu masalahnya.",
  ui_story_30890101_122_dialog_content = "Jadi, kamu masih mengira aku orang yang seperti itu? Serius dan kasar?",
  ui_story_30890101_123_dialog_content = "Ya... Eh, maksudku tidak! Sama sekali tidak! Tidak sedikit pun!!",
  ui_story_30890101_124_dialog_content = "Maksudku, kamu Chief Judge Lumopolis! Aku mengerti jika kamu seperti itu. Itu sangat wajar!",
  ui_story_30890101_125_dialog_content = "Jangan khawatir, aku tidak terkejut kamu berpikir seperti itu.",
  ui_story_30890101_126_dialog_content = "Mungkin aku juga perlu melakukan beberapa perubahan dalam hidup...",
  ui_story_30890101_127_dialog_content = "Bagaimana jika... Bagaimana jika aku mencoba kepribadian yang berbeda, mulai besok? Misalnya, kepribadian yang lucu?",
  ui_story_30890101_128_dialog_content = "H-hah??? Eh, tidak harus setiba-tiba itu...",
  ui_story_30890101_129_dialog_content = "Aku juga tidak mau orang lain menganggapku mengintimidasi.",
  ui_story_30890101_130_dialog_content = "Aku paham, tetapi...",
  ui_story_30890101_131_dialog_content = "Namun, sejujurnya sifatmu saat ini sudah pas apa adanya!",
  ui_story_30890601_1_dialog_content = "Kau...",
  ui_story_30890601_2_dialog_content = "<color=#e8d9bb>Klang! Klang! Klang!</color>",
  ui_story_30890601_3_dialog_content = "Hah?",
  ui_story_30890601_4_dialog_content = "(Pertemuan selalu membuatku terpesona.)",
  ui_story_30890601_5_dialog_content = "(Kalau kita memikirkan betapa luasnya alam semesta dan waktu yang tepat...)",
  ui_story_30890601_6_dialog_content = "(Tanpa usaha apa pun... suatu pertemuan terjadi, begitu saja.)",
  ui_story_30890601_7_dialog_content = "(Seperti sekarang.)",
  ui_story_30890601_8_dialog_content = "(Sebelumnya, aku tak pernah memercayainya...)",
  ui_story_30890601_9_dialog_content = "(Di sebuah tempat yang jauh dari Astra.)",
  ui_story_30890601_10_dialog_content = "(Di stasiun tua yang hanya didatangi oleh segelintir penduduk lokal Koufu-jou.)",
  ui_story_30890601_11_dialog_content = "(Aku bertemu dengan seorang gadis yang mengenakan pakaian setempat yang luar biasa.)",
  ui_story_30890601_12_dialog_content = "(Dia melihat-lihat kartu pos di hadapannya, memilih dengan jari-jarinya yang ramping dan panjang.)",
  ui_story_30890601_13_dialog_content = "(Di luar terasa dingin, tapi butiran keringat mengalir dari dahinya.)",
  ui_story_30890601_14_dialog_content = "(Saat bunga sakura berguguran dengan anggun, kulihat wajahnya yang agak terkejut di antara kelopak-kelopak yang berjatuhan...)",
  ui_story_30890601_15_dialog_content = "PlayerName?",
  ui_story_30890601_16_dialog_content = "Chief Judge?",
  ui_story_30890601_17_dialog_content = "Wah, kebetulan sekali. Apa kau juga sedang berlibur di sini?",
  ui_story_30890601_18_dialog_content = "Kau benar-benar Chief Judge? Aku hampir tidak mengenalimu.",
  ui_story_30890601_19_dialog_content = "Kau ini kenapa?",
  ui_story_30890601_20_dialog_content = "Sudah kubilang, panggil saja aku Irridon.",
  ui_story_30890601_21_dialog_content = "Selain itu, ini kan bukan Lumopolis. Jadi, lupakan saja jabatanku.",
  ui_story_30890601_22_dialog_content = "Irri... Irridon...",
  ui_story_30890601_23_dialog_content = "*Batuk* Kamu menjatuhkan kartu pos.",
  ui_story_30890601_24_dialog_content = "Hah? Aku lupa sedang memegang sesuatu tadi...",
  ui_story_30890601_25_dialog_content = "Jangan khawatir, biar kuambilkan.",
  ui_story_30890601_26_dialog_content = "Terima kasih, Irridon...",
  ui_story_30890601_27_dialog_content = "Kurasa kau tampak benar-benar berbeda dengan yang biasanya.",
  ui_story_30890601_28_dialog_content = "Apa karena... pakaian yang kukenakan?",
  ui_story_30890601_29_dialog_content = "Bukankah ini pakaian daerah Koufu-jou?",
  ui_story_30890601_30_option_content = "Terlihat bagus!",
  ui_story_30890601_31_dialog_content = "Entah harus bilang apa lagi, tapi kurasa itu sangat cocok denganmu!",
  ui_story_30890601_32_option_content = "Sepertinya nyaman!",
  ui_story_30890601_33_dialog_content = "Pasti cocok untuk cuaca dingin seperti ini!",
  ui_story_30890601_34_option_content = "Kelihatannya mahal!",
  ui_story_30890601_35_dialog_content = "... Benarkah?",
  ui_story_30890601_36_dialog_content = "Sebenarnya, aku baru saja tiba di Koufu-jou tadi, dan tak kusangka tempat ini sangat dingin.",
  ui_story_30890601_37_dialog_content = "Jadi, kubeli satu setel saat melihatnya waktu jalan-jalan.",
  ui_story_30890601_38_dialog_content = "Ahem... Soal itu... Apa kamu juga mencari kartu pos?",
  ui_story_30890601_39_dialog_content = "Yah, kudengar dari warga setempat walau tempat ini terpencil...",
  ui_story_30890601_40_dialog_content = "Kartu pos di stasiun tua ini sangat bagus.",
  ui_story_30890601_41_dialog_content = "Kalau kita membeli satu dan menulis pesan untuk diri sendiri... mungkin itu akan terwujud.",
  ui_story_30890601_42_dialog_content = "Kau juga sudah mendengar legenda itu?",
  ui_story_30890601_43_dialog_content = "Tadinya kupikir itu semacam iklan promosi yang aneh...",
  ui_story_30890601_44_dialog_content = "Tapi, mungkin kartu pos di sini benar-benar ajaib.",
  ui_story_30890601_45_dialog_content = "Kenapa kau bisa bilang begitu?",
  ui_story_30890601_46_dialog_content = "Tadi aku menulis di kartu pos...",
  ui_story_30890601_47_dialog_content = "\"Kuharap aku bertemu dengan orang yang sudah ditakdirkan untukku dalam perjalanan.\"",
  ui_story_30890601_48_dialog_content = "Apa?!",
  ui_story_30890601_49_dialog_content = "<color=#e8d9bb>Nguung, nguung, ngung...</color>",
  ui_story_30890601_50_dialog_content = "Maaf, Communicator milikku berbunyi... Sebentar, ya.",
  ui_story_30890601_51_dialog_content = "Demi White Night. Ada yang bisa kubantu, Michenny?",
  ui_story_30890601_52_dialog_content = "(Sepertinya... Chief Judge hari ini lebih baik dibanding biasanya.)",
  ui_story_30890601_53_dialog_content = "(Apa ini keajaiban liburan?)",
  ui_story_30890601_54_dialog_content = "Oh? Petunjuk baru dalam kasus perampokan Raphael?",
  ui_story_30890601_55_dialog_content = "Maksudmu... itu ada hubungannya dengan dia?",
  ui_story_30890601_56_dialog_content = "(Apa dia mendapat kabar buruk, ya? Raut muka Irridon tiba-tiba menjadi serius...)",
  ui_story_30890601_57_dialog_content = "Yah, mmm, baiklah. Aku mengerti, kebetulan aku... *Batuk*.",
  ui_story_30890601_58_dialog_content = "(... Kenapa dia memandangku lalu menoleh?)",
  ui_story_30890601_59_dialog_content = "Maaf membuatmu menunggu lama.",
  ui_story_30890601_60_dialog_content = "Irridon, semua... baik-baik saja?",
  ui_story_30890601_61_dialog_content = "Kenapa tanya begitu?",
  ui_story_30890601_62_dialog_content = "Bukan apa-apa, kok. Mungkin hanya perasaanku saja...",
  ui_story_30890601_63_dialog_content = "Apa kau jadi teringat pada sesuatu yang kaulakukan?",
  ui_story_30890601_64_dialog_content = "Tidak... bukan...",
  ui_story_30890601_65_dialog_content = "(Dia kembali menjadi Chief Judge...? Dia benar-benar berbeda dengan yang barusan.)",
  ui_story_30890601_66_dialog_content = "Bagaimana kalau kaupikir lagi? Kau yakin belum melakukan apa pun?",
  ui_story_30890601_67_dialog_content = "Yah... Sebenarnya, ada pekerjaan yang harus kuselesaikan hari ini...",
  ui_story_30890601_68_dialog_content = "Tapi, aku justru bolos kerja dan keluyuran.",
  ui_story_30890601_69_dialog_content = "Kau membolos kerja?",
  ui_story_30890601_70_dialog_content = "Tapi, pasti ada yang lain. Coba pikirkan lagi.",
  ui_story_30890601_71_dialog_content = "Kemarin, Vice memasak dan aku berpura-pura makan, tapi sebenarnya tidak...",
  ui_story_30890601_72_dialog_content = "Ada yang lain?",
  ui_story_30890601_73_dialog_content = "Aku tidak membalas surat Charon...",
  ui_story_30890601_74_dialog_content = "Aku menerima hadiah dari orang asing...",
  ui_story_30890601_75_dialog_content = "Aku tidak cuci muka tadi pagi...",
  ui_story_30890601_76_dialog_content = "Sebentar... Apa katamu?",
  ui_story_30890601_77_dialog_content = "Maaf... Aku tidak cuci muka tadi pagi.",
  ui_story_30890601_78_dialog_content = "Ini memang mengejutkan, tapi apa tadi katamu sebelumnya?",
  ui_story_30890601_79_dialog_content = "Aku menerima hadiah... dari orang asing?",
  ui_story_30890601_80_dialog_content = "Di mana? Kapan?",
  ui_story_30890601_81_dialog_content = "Di... Lumopolis. Kemarin, di malam sebelum aku berangkat dari Lumopolis.",
  ui_story_30890601_82_dialog_content = "Di mana hadiahnya sekarang?",
  ui_story_30890601_83_dialog_content = "Hatsyiii!",
  ui_story_30890601_84_dialog_content = "Kau kedinginan?",
  ui_story_30890601_85_dialog_content = "Mungkin... dan mungkin bajuku kurang tebal.",
  ui_story_30890601_86_dialog_content = "Kenapa tidak mengenakan pakaian lain?",
  ui_story_30890601_87_dialog_content = "(Mana mungkin aku bilang bahwa uangku tidak cukup...)",
  ui_story_30890601_88_dialog_content = "*Batuk* Aku tahu ini agak berantakan, tapi... ini dia gudangnya.",
  ui_story_30890601_89_dialog_content = "Setelah menerima hadiah itu, apa kau membukanya untuk melihat isinya?",
  ui_story_30890601_90_dialog_content = "Aku khawatir isinya hanyalah tipuan, jadi aku menyimpannya di gudang...",
  ui_story_30890601_91_dialog_content = "Kau sering menerima hadiah dari orang iseng?",
  ui_story_30890601_92_dialog_content = "*Batuk* Bukan itu... intinya.",
  ui_story_30890601_93_dialog_content = "Memangnya... ada yang salah dengan hadiah yang kuterima?",
  ui_story_30890601_94_dialog_content = "Belum lama ini, sebuah geng maling melakukan perampokan serius di Lumopolis.",
  ui_story_30890601_95_dialog_content = "Jadi, hadiah yang kau terima mungkin barang curian!",
  ui_story_30890601_96_dialog_content = "Hatsyiii... Biar kuperiksa!",
  ui_story_30890601_97_dialog_content = "Yang di sebelah kirimu?",
  ui_story_30890601_98_dialog_content = "Biar kulihat...",
  ui_story_30890601_99_dialog_content = "<color=#e8d9bb>Ding! Dang! Klang! Dor!</color>",
  ui_story_30890601_100_dialog_content = "*Batuk* Siapa yang menaruh semua komponen mesin rusak ini di sini...?",
  ui_story_30890601_101_dialog_content = "Bukan itu, ya...? Nah, itu dia. Di depanmu.",
  ui_story_30890601_102_dialog_content = "<color=#e8d9bb>Ding! Dang! Klang! Dor!</color>",
  ui_story_30890601_103_dialog_content = "Benda apa yang seperti kempa ini?",
  ui_story_30890601_104_dialog_content = "Haha, ini alat penjepitku yang berharga! Aku menggunakannya untuk menguji kekuatanku sesekali!",
  ui_story_30890601_105_dialog_content = "Hah? Kenapa mudah sekali?!",
  ui_story_30890601_106_dialog_content = "Hatsyiii... Aku tidak sadar sudah bertambah kuat.",
  ui_story_30890601_107_dialog_content = "Sebentar, mustahil. Pasti ada orang yang merusak alat penjepitku!",
  ui_story_30890601_108_dialog_content = "... Kurasa sebaiknya kauseka dulu hidungmu.",
  ui_story_30890601_109_dialog_content = "Hatsyiii! Terima kasih sudah mengingatkan, Chief Judge...",
  ui_story_30890601_110_dialog_content = "Kotak apa yang ada di kananmu?",
  ui_story_30890601_111_dialog_content = "Ah, iya! Ini dia! Ini hadiah yang kuterima dari orang asing itu.",
  ui_story_30890601_112_dialog_content = "Biar kuambil agar kau bisa memeriksanya!",
  ui_story_30890601_113_dialog_content = "Tidak usah buru-buru. Hati-hati melangkah.",
  ui_story_30890601_114_dialog_content = "<color=#e8d9bb>Ding! Dang! Klang! Dor!</color>",
  ui_story_30890601_115_dialog_content = "<size=45><color=#e8d9bb>Duar—!</color></size>",
  ui_story_30890601_116_dialog_content = "... PlayerName, kau baik-baik saja?",
  ui_story_30890601_117_dialog_content = "M-maafkan aku, Chief Judge.",
  ui_story_30890601_118_dialog_content = "Aku jatuh menimpa hadiahnya, lalu sepertinya aku merusaknya.",
  ui_story_30890601_119_dialog_content = "Tapi, aneh. Meskipun aku jatuh...",
  ui_story_30890601_120_dialog_content = "Aku sama sekali tidak kesakitan...",
  ui_story_30890601_121_dialog_content = "Punggungku tidak nyeri, kakiku tidak sakit, dan aku bahkan tidak bersin-bersin lagi!",
  ui_story_30890601_122_dialog_content = "Apa yang terjadi...?",
  ui_story_30890601_123_dialog_content = "Kau tidak paham, ya? Kau jadi sembuh setelah hadiah itu meledak. Menurutmu, apa isinya?",
  ui_story_30890601_124_dialog_content = "Jangan-jangan ini... Holy Water Shell milik Raphael?!",
  ui_story_30890601_125_dialog_content = "Maksudmu, orang asing yang berpakaian hitam itu adalah Raphael?",
  ui_story_30890601_126_dialog_content = "Kalau diberikan oleh Raphael, aku tak perlu menyelidikinya.",
  ui_story_30890601_127_dialog_content = "Kau benar. Perlu beberapa Raphael yang ditumpuk satu sama lain agar tingginya sama dengan orang asing itu.",
  ui_story_30890601_128_dialog_content = "Maksudmu, orang asing itu mencuri barang Raphael dan memberikannya padaku? Kenapa...?",
  ui_story_30890601_129_dialog_content = "Ada hal lain yang kauingat soal orang asing itu?",
  ui_story_30890601_130_dialog_content = "Seingatku orang asing itu mengenakan pakaian rapat berwarna hitam dari kepala sampai kaki.",
  ui_story_30890601_131_dialog_content = "Langkah mereka juga sempoyongan, seolah-olah tubuh bagian atas dan bawahnya tidak terhubung.",
  ui_story_30890601_132_dialog_content = "Setelah memberiku hadiah, mereka hanya berbalik dan berjalan pergi...",
  ui_story_30890601_133_dialog_content = "Sempoyongan... Kau mencium bau alkohol?",
  ui_story_30890601_134_dialog_content = "Sama sekali tidak... Tapi, tepat sebelum orang asing itu pergi, kudengar suara kokok ayam betina!",
  ui_story_30890601_135_dialog_content = "Kalau kupikir-pikir, itu sangat aneh!",
  ui_story_30890601_136_dialog_content = "Begitu rupanya...",
  ui_story_30890601_137_dialog_content = "Chief Judge... Kautahu siapa orang asing berpakaian hitam itu?",
  ui_story_30890601_138_dialog_content = "Hanya ada satu orang yang terpikir di kepalaku...",
  ui_story_30890601_139_dialog_content = "Keating!",
  ui_story_30890601_140_dialog_content = "Keating? Mana mungkin? Kita harus menumpuk mereka agar bisa setinggi orang asing berpakaian hitam itu...",
  ui_story_30890601_141_dialog_content = "Sebentar, maksudmu, mereka saling bertumpukan dan berpura-pura menjadi orang asing berpakaian hitam?!",
  ui_story_30890601_142_dialog_content = "Tapi, kenapa mereka sampai repot-repot begitu demi memberiku hadiah...?",
  ui_story_30890601_143_dialog_content = "Motifnya tetap menjadi misteri... Ada pesan apa pun di dalam kotak hadiah itu?",
  ui_story_30890601_144_dialog_content = "Biar kulihat... Eh, sebentar... Memang ada catatannya! Bunyinya...",
  ui_story_30890601_145_dialog_content = "\"Hei, orang yang malang dan menyedihkan. Jangan sedih lagi.\"",
  ui_story_30890601_146_dialog_content = "\"Terimalah hadiah ini agar kau jadi kaya.\"",
  ui_story_30890601_147_dialog_content = "\"Dari: GNITAEK.\"",
  ui_story_30890601_148_dialog_content = "Baiklah... Sekarang aku yakin bahwa orang asing itu adalah Keating.",
  ui_story_30890601_149_dialog_content = "*Menghela napas* Dasar anak-anak itu...",
  ui_story_30890601_150_dialog_content = "Sepertinya mereka perlu pendidikan yang layak... agar mereka bisa berbuat baik dengan cara yang benar dan jujur.",
  ui_story_30890601_151_dialog_content = "Tapi, kenapa? Kenapa mereka mengira aku butuh bantuan?",
  ui_story_30890601_152_dialog_content = "Apa karena aku selalu mengenakan pakaian yang itu-itu saja? Tapi...",
  ui_story_30890601_153_dialog_content = "Demi White Night! Dengan resmi kunyatakan bahwa kasus ini sudah selesai.",
  ui_story_30890601_154_dialog_content = "Haha! Ayo kita pergi, PlayerName!",
  ui_story_30890601_155_dialog_content = "Hah? Ke mana? Maksudmu...",
  ui_story_30890601_156_option_content = "Penjara Lumopolis?",
  ui_story_30890601_157_dialog_content = "Yah, aku sudah tahu kalau itu hanya kesalahpahaman.",
  ui_story_30890601_158_dialog_content = "Liburan seperti ini kan jarang terjadi. Ayo, kita melanjutkan perjalanan ke Koufu-jou.",
  ui_story_30890601_159_option_content = "Stasiun yang menjual kartu pos?",
  ui_story_30890601_160_dialog_content = "Ahh, kamu belum sempat beli apa-apa karena kesalahpahaman barusan, ya?",
  ui_story_30890601_161_dialog_content = "Oke, tapi...",
  ui_story_30890601_162_dialog_content = "Jangan khawatir soal biayanya. Biar aku yang membayar semuanya hari ini!",
  ui_story_30890601_163_dialog_content = "A-apa semua orang benar-benar mengira aku tidak punya uang...?",
  ui_story_30890602_1_dialog_content = "<color=#e8d9bb>Whoooosh—</color>",
  ui_story_30890602_2_dialog_content = "(Sebuah angin lembut bertiup di udara. Berdiri di depanku adalah seorang gadis dengan mata dan rambut seemas dan seberapi matahari.)",
  ui_story_30890602_3_dialog_content = "(Kepada semua orang, dia adalah seorang Chief Judge yang anggun, jauh, dan tidak tersenyum.)",
  ui_story_30890602_4_dialog_content = "(Tapi sekarang, dia menunjukkan sisi yang berbeda darinya, sisi yang dia sembunyikan dengan baik di balik topengnya...)",
  ui_story_30890602_5_dialog_content = "PlayerName…",
  ui_story_30890602_6_dialog_content = "Apakah benar-benar tidak apa-apa?",
  ui_story_30890602_7_dialog_content = "<color=#e8d9bb>Sebelumnya hari itu</color>",
  ui_story_30890602_8_dialog_content = "Huff, puff... Maaf membuatmu menunggu!",
  ui_story_30890602_9_dialog_content = "Kamu tidak perlu minta maaf. Saya tidak menunggu terlalu lama.",
  ui_story_30890602_10_dialog_content = "Jika ada, saya harus berterima kasih karena kamu menemani saya minum secangkir teh.",
  ui_story_30890602_11_dialog_content = "Ehem, sejujurnya, aku sudah ingin mengunjungimu sejak beberapa waktu lalu, hanya untuk memastikan kamu baik-baik saja.",
  ui_story_30890602_12_dialog_content = "Aku membuatmu khawatir, bukan...?",
  ui_story_30890602_13_dialog_content = "Tapi aku bisa menjamin, aku baik-baik saja. Lagipula, sebagai Hakim Kepala Lumopolis, aku tidak bisa terkalahkan dengan mudah.",
  ui_story_30890602_14_dialog_content = "Setelah terbangun dari mimpi panjang dan membingungkan itu, saya rasa akhirnya saya menemukan jalan masa depan saya.",
  ui_story_30890602_15_dialog_content = "Satu per satu, saya mulai perlahan mengatasi masalah-masalah masa lalu yang dulu membuat saya merasa tidak berdaya dan tersesat.",
  ui_story_30890602_16_dialog_content = "Sebelumnya, saya memaksa diri untuk menjadi Hakim Ketua yang sempurna, yang layak atas harapan dan ekspektasi semua orang. Tapi sekarang...",
  ui_story_30890602_17_dialog_content = "Akhirnya saya menyadari bahwa saya tidak perlu lagi berpura-pura menjadi orang lain. Saya adalah diri saya, dan itu lebih dari cukup.",
  ui_story_30890602_18_dialog_content = "Jadi terima kasih, PlayerName. Terima kasih telah membangunkan saya dari mimpi buruk itu.",
  ui_story_30890602_19_option_content = "Sama-sama!",
  ui_story_30890602_20_dialog_content = "Saya hanya melakukan apa yang seharusnya saya lakukan!",
  ui_story_30890602_21_option_content = "Tidak perlu berterima kasih padaku...",
  ui_story_30890602_22_dialog_content = "Aku sebenarnya tidak melakukan apa-apa... Kamu lah yang menyelamatkan dirimu sendiri!",
  ui_story_30890602_23_dialog_content = "Hahaha! Tetap rendah hati seperti biasanya.",
  ui_story_30890602_24_dialog_content = "Dalam hal lain, aku berharap kamu bisa menemani saya untuk menemui seseorang hari ini.",
  ui_story_30890602_25_dialog_content = "Aku masih merasa agak bersalah, dan sepertinya aku tidak bisa mengambil langkah pertama itu sendiri.",
  ui_story_30890602_26_dialog_content = "Oh... Apakah itu sebabnya kamu mengenakan pakaian yang berbeda hari ini?",
  ui_story_30890602_27_dialog_content = "Ya. Ini adalah pakaian lamaku saat masih menjadi ksatria. Saya terkejut masih muat dengan baik setelah bertahun-tahun.",
  ui_story_30890602_28_dialog_content = "Tapi bahkan saat itu, aku masih menghindari masalah yang telah kubur dalam-dalam di hatiku.",
  ui_story_30890602_29_dialog_content = "Tahun-tahun telah berlalu dan orang-orang telah berubah, tetapi masalah tersebut masih terikat erat dengan tempat itu.",
  ui_story_30890602_30_dialog_content = "Jika mimpi burukku menunjukkan sesuatu, saatnya bagi saya untuk menghadapi iblis dalam diri dan menyelesaikan masalah ini, sekali untuk selamanya.",
  ui_story_30890602_31_dialog_content = "Tapi tanpa kamu di sana untuk mengawasi saya, aku khawatir aku tidak akan memiliki keberanian untuk melakukannya.",
  ui_story_30890602_32_dialog_content = "Kamu sudah berhasil mengalahkan mimpi burukmu dan merebut kembali dirimu yang sebenarnya... Apa lagi yang bisa menakutkanmu sekarang?",
  ui_story_30890602_33_option_content = "Kecuali…",
  ui_story_30890602_34_dialog_content = "Apakah itu ayahmu?",
  ui_story_30890602_35_dialog_content = "Ya.",
  ui_story_30890602_36_option_content = "Aku nggak paham...",
  ui_story_30890602_37_dialog_content = "Ini... ayahku.",
  ui_story_30890602_38_dialog_content = "Sungguh memalukan untuk mengatakannya, tetapi meskipun ayah saya meninggal untuk melindungi saya... Saya belum pernah mengunjungi kuburannya untuk memberikan penghormatan. Bahkan tidak satu kali pun.",
  ui_story_30890602_39_dialog_content = "Aku... Aku masih belum bisa menghadapinya. Setiap kali aku melewati kuburan, aku merasa terdorong untuk berjalan secepat mungkin.",
  ui_story_30890602_40_dialog_content = "Tapi sekarang... Kamu punya sesuatu yang penting untuk dikatakan kepadanya, bukan?",
  ui_story_30890602_41_dialog_content = "Aku tahu, dan itu sesuatu yang harus diungkapkan... Tapi aku masih takut.",
  ui_story_30890602_42_dialog_content = "Kalau begitu, aku akan ikut denganmu! Meskipun kita tidak akan mendapatkan jawaban darinya sekarang, tindakan memberi tahu dia seharusnya memberimu jawaban yang kamu butuhkan!",
  ui_story_30890602_43_dialog_content = "PlayerName... Aku tahu meminta bantuanmu adalah keputusan yang tepat.",
  ui_story_30890602_44_dialog_content = "Apakah Anda berencana membawakan sesuatu untuknya?",
  ui_story_30890602_45_dialog_content = "Emm... Tidak. Ayah selalu membenci menerima hadiah, terutama yang berharga.",
  ui_story_30890602_46_dialog_content = "Tapi bagaimana bisa ada yang membenci menerima hadiah? Hmm... Apakah dia punya hobi di masa lalu?",
  ui_story_30890602_47_dialog_content = "Tidak begitu. Semangat Ayah selalu pada pekerjaannya, tetapi saat tidak bekerja, dia akan merawat bunga-bunga di taman ini...",
  ui_story_30890602_48_dialog_content = "Terkadang, aku bahkan merasa iri pada bunga-bunga itu. Satu-satunya saat ayahku menunjukkan belas kasihan adalah ketika dia merawat mereka.",
  ui_story_30890602_49_dialog_content = "Dan, sekarang kamulah yang akan merawat bunga-bunga ini, 'kan?",
  ui_story_30890602_50_dialog_content = "Ya... Ironis, bukan?",
  ui_story_30890602_51_dialog_content = "Sama sekali tidak! Bunga-bunga ini terlihat sehat dan cantik menurutku!",
  ui_story_30890602_52_dialog_content = "Jadi, mengapa kamu tidak memilih beberapa untuk ayahmu? Dengan begitu, dia juga bisa melihat betapa baiknya kamu merawat mereka.",
  ui_story_30890602_53_dialog_content = "Benarkah...?",
  ui_story_30890602_54_dialog_content = "\"Di sini berbaring Rodell Novek...\" Irridon, aku menemukannya!",
  ui_story_30890602_55_dialog_content = "Hah? Hei, kamu baik-baik saja...?",
  ui_story_30890602_56_dialog_content = "...",
  ui_story_30890602_57_dialog_content = "Aku tahu ini pasti sangat sulit untukmu. Aku bisa mengantarmu kembali, jika itu yang kamu inginkan...",
  ui_story_30890602_58_dialog_content = "Tidak, PlayerName. Kurasa aku akhirnya siap.",
  ui_story_30890602_59_dialog_content = "Fiuh…",
  ui_story_30890602_60_dialog_content = "Halo, Ayah. Ini aku, Irridon... Maaf sudah lama. Akhirnya aku mengumpulkan keberanian untuk menemui Anda.",
  ui_story_30890602_61_dialog_content = "Selama bertahun-tahun, hanya memikirkan menghadapi Anda membuat saya merasa malu. Saya takut Anda masih menganggap saya \"tak berguna\" karena tidak menunjukkan pertumbuhan.",
  ui_story_30890602_62_dialog_content = "Aku masih tidak mengerti kenapa kamu mau mengorbankan hidupmu sendiri untuk menyelamatkan orang \"tak berguna\" seperti aku...",
  ui_story_30890602_63_dialog_content = "Tapi aku berdoa suatu hari nanti, saat aku akhirnya memenuhi harapanmu, aku bisa mengatakan bahwa aku melakukannya dengan bangga!",
  ui_story_30890602_64_dialog_content = "Sayangnya... Sepertinya hari itu masih sangat jauh.",
  ui_story_30890602_65_dialog_content = "Tapi meskipun begitu, saya tidak takut lagi. Saya ingin memberi tahu Anda bahwa setelah bertahun-tahun... Saya tidak selemah yang dulu saya pikirkan.",
  ui_story_30890602_66_dialog_content = "Saya sekarang Hakim Ketua, yang mantap dalam tujuan dan keyakinannya.",
  ui_story_30890602_67_dialog_content = "Meskipun aku bukanlah sosok yang kamu inginkan, aku akan terus berusaha menjadi versi terbaik dari diriku...",
  ui_story_30890602_68_dialog_content = "Karena seperti kamu, Ayah... Saya tidak menginginkan apa pun selain melindungi kota murni dan indah ini di langit.",
  ui_story_30890602_69_dialog_content = "Akhirnya aku mengerti sekarang. Kamu tidak pernah membenci aku; kamu hanya menggunakan cara yang paling tidak langsung untuk menunjukkan cintamu padaku...",
  ui_story_30890602_70_dialog_content = "Jadi, tolong terus awasi saya. Saya akan terus maju... Tapi dengan cara saya sendiri.",
  ui_story_30890602_71_dialog_content = "Saya benar-benar percaya... bahwa ini adalah cara terbaik untuk membalas kebaikanmu...",
  ui_story_30890602_72_dialog_content = "<color=#e8d9bb>Whoooosh—</color>",
  ui_story_30890602_73_dialog_content = "PlayerName... Apakah benar-benar baik-baik saja?",
  ui_story_30890602_74_option_content = "Tentu saja!",
  ui_story_30890602_75_option_content = "Itu sempurna!",
  ui_story_30890602_76_dialog_content = "Aku yakin dia mendengarmu, keras dan jelas!",
  ui_story_30890602_77_dialog_content = "Kamu benar... Aku yakin dia mendengar setiap kata."
}
return config
